(async()=>{const save=document.querySelector('.save-guide'),note=document.querySelector('.save-status');const path=location.pathname;const article=/\/(journal|destinations|comparisons)\/[^/]+\/?$/.test(path);if(!save&&!article&&!path.endsWith('/search/'))return;let state;try{const r=await fetch('/api/portal',{cache:'no-store'});if(!r.ok)throw Error();state=await r.json()}catch{if(save)save.onclick=()=>{location.href='/signin-with-chatgpt?return_to='+encodeURIComponent(path)};return}async function change(action){const r=await fetch('/api/portal',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...action,version:state.version})});const d=await r.json();if(!r.ok)throw Error(d.error);state=d}function label(){if(save)save.textContent=state.data.bookmarks.some(x=>x.path===path)?window.DIY_T("✓ Saved to account · Remove"):window.DIY_T("＋ Save to My Trip")}if(state.data.historyConsent){const q=new URLSearchParams(location.search).get('q');try{await change({type:'history',path:q?path+'?q='+encodeURIComponent(q.slice(0,120)):path,title:(q?window.DIY_T("Search: ")+q:document.title.split(' | ')[0]).slice(0,160)})}catch{}}label();if(save)save.onclick=async()=>{save.disabled=true;try{await change(state.data.bookmarks.some(x=>x.path===path)?{type:'removeBookmark',path}:{type:'bookmark',path,title:document.title.split(' | ')[0].slice(0,160)});label();note.textContent=window.DIY_T("Account updated.")}catch(e){note.textContent=window.DIY_T(e.message)}finally{save.disabled=false}}})();
